// Ingest Pipeline for Product Events
export const ProductEventPipeline = new IngestPipeline<ProductEvent>(
  "ProductEvent",
  {
    ingestApi: true,  // POST /ingest/ProductEvent
    stream: true,     // Redpanda topic "ProductEvent"
    table: {          // ClickHouse table local.ProductEvent
      orderByFields: ["event_type", "product_id", "event_ts"]
    },
  }
);

// Materialized View: Top Products Aggregation
interface TopProductsRow {
  product_id: string;
  view_count: number;
  cart_count: number;
  purchase_count: number;
  total_revenue: number;
}

export const topProductsMV = new MaterializedView<TopProductsRow>({
  tableName: "TopProducts",
  materializedViewName: "top_products_mv",
  orderByFields: ["total_revenue", "product_id"],
  selectStatement: sql`
    SELECT
      product_id,
      countIf(event_type = 'view') AS view_count,
      countIf(event_type = 'cart') AS cart_count,
      countIf(event_type = 'purchase') AS purchase_count,
      sumIf(JSONExtractFloat(properties, 'price'), event_type = 'purchase') AS total_revenue
    FROM ProductEvent
    GROUP BY product_id
  `,
  selectTables: [ProductEventPipeline.table!],
});

// Materialized View: Conversion Funnel
interface ConversionFunnelRow {
  step: string;
  unique_users: number;
  total_events: number;
}

export const conversionFunnelMV = new MaterializedView<ConversionFunnelRow>({
  tableName: "ConversionFunnel",
  materializedViewName: "conversion_funnel_mv",
  orderByFields: ["step"],
  selectStatement: sql`
    SELECT
      event_type AS step,
      uniq(user_id) AS unique_users,
      count() AS total_events
    FROM ProductEvent
    GROUP BY event_type
  `,
  selectTables: [ProductEventPipeline.table!],
});

// Materialized View: Hourly Activity
interface HourlyActivityRow {
  hour: Date;
  event_type: string;
  event_count: number;
}

export const hourlyActivityMV = new MaterializedView<HourlyActivityRow>({
  tableName: "HourlyActivity",
  materializedViewName: "hourly_activity_mv",
  orderByFields: ["hour", "event_type"],
  selectStatement: sql`
    SELECT
      toStartOfHour(event_ts) AS hour,
      event_type,
      count() AS event_count
    FROM ProductEvent
    GROUP BY hour, event_type
  `,
  selectTables: [ProductEventPipeline.table!],
});

export const hourlyActivityMV = new MaterializedView<HourlyActivityRow>({
  tableName: "HourlyActivity",
  materializedViewName: "hourly_activity_mv",
  orderByFields: ["hour", "event_type"],
  selectStatement: sql`
    SELECT
      toStartOfHour(event_ts) AS hour,
      event_type,
      count() AS event_count
    FROM ProductEvent
    GROUP BY hour, event_type
  `,
  selectTables: [ProductEventPipeline.table!],
});

// API Endpoints

// Top Products API
interface TopProductsInput { limit?: number; }

export const topProductsApi = new Api<TopProductsInput, TopProductsRow>(
  "top-products",
  async ({ limit = 10 }, { client, sql }) => {
    const result = await client.query.execute(sql`
      SELECT *
      FROM TopProducts
      ORDER BY total_revenue DESC, view_count DESC
      LIMIT ${limit}
    `);
    return await result.json();
  }
);

// Conversion Funnel API
interface ConversionFunnelInput {}

export const conversionFunnelApi = new Api<ConversionFunnelInput, ConversionFunnelRow>(
  "conversion-funnel",
  async ({}, { client, sql }) => {
    const result = await client.query.execute(sql`
      SELECT *
      FROM ConversionFunnel
      ORDER BY
        CASE step
          WHEN 'view' THEN 1
          WHEN 'cart' THEN 2
          WHEN 'purchase' THEN 3
          ELSE 4
        END
    `);
    return await result.json();
  }
);

// Hourly Activity API
interface HourlyActivityInput {
  hours?: number;  // Number of recent hours to return, defaults to 24
}

export const hourlyActivityApi = new Api<HourlyActivityInput, HourlyActivityRow>(
  "hourly-activity",
  async ({ hours = 24 }, { client, sql }) => {
    const result = await client.query.execute(sql`
      SELECT *
      FROM HourlyActivity
      WHERE hour >= subtractHours(now(), ${hours})
      ORDER BY hour DESC, event_type
    `);
    return await result.json();
  }
);

